with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'الرصد الراداري والفضائي ومعالجة البيانات الجوية','الأسس الفيزيائية والتشغيلية للرادار والأقمار الصناعية ومعالجة منتجات الاستشعار عن بعد ودمجها.',31,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'تشغيل رادارات الطقس وتحليل منتجاتها',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الأقمار الصناعية والدمج متعدد المصادر',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('weather-radar-system-components','مكونات منظومة رادار الطقس','المرسل والمستقبل والهوائي والمعالجة وأنظمة المعايرة.','{"blocks":[{"type":"text","text":"يتناول الدرس مكونات منظومة رادار الطقس ضمن تطبيقات الرصد الجوي والاستشعار عن بعد، مع ربط المبدأ الفيزيائي بالمنتج التشغيلي."},{"type":"text","text":"المفهوم الرئيس: المرسل والمستقبل والهوائي والمعالجة وأنظمة المعايرة.، ويجب تفسيره مع معرفة خصائص الجهاز والهندسة والظروف البيئية."},{"type":"text","text":"يبدأ التحليل بتحديد مصدر البيانات وإصدار المنتج والتوقيت والإحداثيات والوحدات والدقة المكانية والزمنية."},{"type":"text","text":"تراجع بيانات المعايرة والبيانات الوصفية وأعلام الجودة قبل تفسير القيم أو مقارنتها."},{"type":"text","text":"تحدد القيود المرتبطة بالمدى وزاوية الرصد والتضاريس والسحب والسطح والتداخل بين الإشارات بحسب نوع المستشعر."},{"type":"text","text":"تفسر المنتجات على أنها قياسات أو استرجاعات لها افتراضات، وليست وصفاً كاملاً مباشراً لكل خصائص الغلاف الجوي."},{"type":"text","text":"تدمج المنتجات مع المحطات والسبر والنماذج عند الحاجة، مع مراعاة اختلاف أوقات الرصد ومجالات التغطية."},{"type":"text","text":"تستخدم المقارنات الزمنية والمكانية لاكتشاف التطور والأنماط، مع تجنب تفسير الفجوات على أنها غياب للظاهرة."},{"type":"text","text":"توثق خطوات المعالجة والمرشحات والتحويلات وإعدادات العرض حتى تكون النتيجة قابلة لإعادة الإنتاج."},{"type":"text","text":"تقيّم جودة المنتج بمقارنته بمرجع مستقل وبفهم طبيعة الخطأ والتحيز وعدم اليقين."},{"type":"text","text":"مثال تطبيقي: إعداد خريطة تحليلية تتضمن المنتج الأصلي وأعلام الجودة ومناطق الثقة وملاحظات التحقق الأرضي."},{"type":"callout","text":"الخلاصة: القيمة التشغيلية للاستشعار عن بعد تعتمد على فهم القياس وحدوده ودمجه مع مصادر الرصد الأخرى."}]}',2560,60,'["شرح المبدأ الفيزيائي للمنتج","تقييم جودة القياس وحدود الاسترجاع","دمج المنتج مع مصادر الرصد الأخرى"]','تشغيل رادارات الطقس وتحليل منتجاتها'),
('radar-reflectivity-calibration','معايرة الانعكاسية الرادارية وجودة القياس','العلاقة بين القدرة المستقبلة والانعكاسية وتصحيحات النظام.','{"blocks":[{"type":"text","text":"يتناول الدرس معايرة الانعكاسية الرادارية وجودة القياس ضمن تطبيقات الرصد الجوي والاستشعار عن بعد، مع ربط المبدأ الفيزيائي بالمنتج التشغيلي."},{"type":"text","text":"المفهوم الرئيس: العلاقة بين القدرة المستقبلة والانعكاسية وتصحيحات النظام.، ويجب تفسيره مع معرفة خصائص الجهاز والهندسة والظروف البيئية."},{"type":"text","text":"يبدأ التحليل بتحديد مصدر البيانات وإصدار المنتج والتوقيت والإحداثيات والوحدات والدقة المكانية والزمنية."},{"type":"text","text":"تراجع بيانات المعايرة والبيانات الوصفية وأعلام الجودة قبل تفسير القيم أو مقارنتها."},{"type":"text","text":"تحدد القيود المرتبطة بالمدى وزاوية الرصد والتضاريس والسحب والسطح والتداخل بين الإشارات بحسب نوع المستشعر."},{"type":"text","text":"تفسر المنتجات على أنها قياسات أو استرجاعات لها افتراضات، وليست وصفاً كاملاً مباشراً لكل خصائص الغلاف الجوي."},{"type":"text","text":"تدمج المنتجات مع المحطات والسبر والنماذج عند الحاجة، مع مراعاة اختلاف أوقات الرصد ومجالات التغطية."},{"type":"text","text":"تستخدم المقارنات الزمنية والمكانية لاكتشاف التطور والأنماط، مع تجنب تفسير الفجوات على أنها غياب للظاهرة."},{"type":"text","text":"توثق خطوات المعالجة والمرشحات والتحويلات وإعدادات العرض حتى تكون النتيجة قابلة لإعادة الإنتاج."},{"type":"text","text":"تقيّم جودة المنتج بمقارنته بمرجع مستقل وبفهم طبيعة الخطأ والتحيز وعدم اليقين."},{"type":"text","text":"مثال تطبيقي: إعداد خريطة تحليلية تتضمن المنتج الأصلي وأعلام الجودة ومناطق الثقة وملاحظات التحقق الأرضي."},{"type":"callout","text":"الخلاصة: القيمة التشغيلية للاستشعار عن بعد تعتمد على فهم القياس وحدوده ودمجه مع مصادر الرصد الأخرى."}]}',2570,60,'["شرح المبدأ الفيزيائي للمنتج","تقييم جودة القياس وحدود الاسترجاع","دمج المنتج مع مصادر الرصد الأخرى"]','تشغيل رادارات الطقس وتحليل منتجاتها'),
