('radar-clutter-and-attenuation','التشويش والتوهين وحجب الشعاع','تمييز الأهداف غير الجوية وتصحيح حدود الرصد.','{"blocks":[{"type":"text","text":"يتناول الدرس التشويش والتوهين وحجب الشعاع ضمن تطبيقات الرصد الجوي والاستشعار عن بعد، مع ربط المبدأ الفيزيائي بالمنتج التشغيلي."},{"type":"text","text":"المفهوم الرئيس: تمييز الأهداف غير الجوية وتصحيح حدود الرصد.، ويجب تفسيره مع معرفة خصائص الجهاز والهندسة والظروف البيئية."},{"type":"text","text":"يبدأ التحليل بتحديد مصدر البيانات وإصدار المنتج والتوقيت والإحداثيات والوحدات والدقة المكانية والزمنية."},{"type":"text","text":"تراجع بيانات المعايرة والبيانات الوصفية وأعلام الجودة قبل تفسير القيم أو مقارنتها."},{"type":"text","text":"تحدد القيود المرتبطة بالمدى وزاوية الرصد والتضاريس والسحب والسطح والتداخل بين الإشارات بحسب نوع المستشعر."},{"type":"text","text":"تفسر المنتجات على أنها قياسات أو استرجاعات لها افتراضات، وليست وصفاً كاملاً مباشراً لكل خصائص الغلاف الجوي."},{"type":"text","text":"تدمج المنتجات مع المحطات والسبر والنماذج عند الحاجة، مع مراعاة اختلاف أوقات الرصد ومجالات التغطية."},{"type":"text","text":"تستخدم المقارنات الزمنية والمكانية لاكتشاف التطور والأنماط، مع تجنب تفسير الفجوات على أنها غياب للظاهرة."},{"type":"text","text":"توثق خطوات المعالجة والمرشحات والتحويلات وإعدادات العرض حتى تكون النتيجة قابلة لإعادة الإنتاج."},{"type":"text","text":"تقيّم جودة المنتج بمقارنته بمرجع مستقل وبفهم طبيعة الخطأ والتحيز وعدم اليقين."},{"type":"text","text":"مثال تطبيقي: إعداد خريطة تحليلية تتضمن المنتج الأصلي وأعلام الجودة ومناطق الثقة وملاحظات التحقق الأرضي."},{"type":"callout","text":"الخلاصة: القيمة التشغيلية للاستشعار عن بعد تعتمد على فهم القياس وحدوده ودمجه مع مصادر الرصد الأخرى."}]}',2600,60,'["شرح المبدأ الفيزيائي للمنتج","تقييم جودة القياس وحدود الاسترجاع","دمج المنتج مع مصادر الرصد الأخرى"]','تشغيل رادارات الطقس وتحليل منتجاتها'),
('radar-qpe-precipitation-estimation','تقدير الهطول الكمي من الرادار','تحويل الانعكاسية إلى معدلات مطر وتقييم عدم اليقين.','{"blocks":[{"type":"text","text":"يتناول الدرس تقدير الهطول الكمي من الرادار ضمن تطبيقات الرصد الجوي والاستشعار عن بعد، مع ربط المبدأ الفيزيائي بالمنتج التشغيلي."},{"type":"text","text":"المفهوم الرئيس: تحويل الانعكاسية إلى معدلات مطر وتقييم عدم اليقين.، ويجب تفسيره مع معرفة خصائص الجهاز والهندسة والظروف البيئية."},{"type":"text","text":"يبدأ التحليل بتحديد مصدر البيانات وإصدار المنتج والتوقيت والإحداثيات والوحدات والدقة المكانية والزمنية."},{"type":"text","text":"تراجع بيانات المعايرة والبيانات الوصفية وأعلام الجودة قبل تفسير القيم أو مقارنتها."},{"type":"text","text":"تحدد القيود المرتبطة بالمدى وزاوية الرصد والتضاريس والسحب والسطح والتداخل بين الإشارات بحسب نوع المستشعر."},{"type":"text","text":"تفسر المنتجات على أنها قياسات أو استرجاعات لها افتراضات، وليست وصفاً كاملاً مباشراً لكل خصائص الغلاف الجوي."},{"type":"text","text":"تدمج المنتجات مع المحطات والسبر والنماذج عند الحاجة، مع مراعاة اختلاف أوقات الرصد ومجالات التغطية."},{"type":"text","text":"تستخدم المقارنات الزمنية والمكانية لاكتشاف التطور والأنماط، مع تجنب تفسير الفجوات على أنها غياب للظاهرة."},{"type":"text","text":"توثق خطوات المعالجة والمرشحات والتحويلات وإعدادات العرض حتى تكون النتيجة قابلة لإعادة الإنتاج."},{"type":"text","text":"تقيّم جودة المنتج بمقارنته بمرجع مستقل وبفهم طبيعة الخطأ والتحيز وعدم اليقين."},{"type":"text","text":"مثال تطبيقي: إعداد خريطة تحليلية تتضمن المنتج الأصلي وأعلام الجودة ومناطق الثقة وملاحظات التحقق الأرضي."},{"type":"callout","text":"الخلاصة: القيمة التشغيلية للاستشعار عن بعد تعتمد على فهم القياس وحدوده ودمجه مع مصادر الرصد الأخرى."}]}',2610,60,'["شرح المبدأ الفيزيائي للمنتج","تقييم جودة القياس وحدود الاسترجاع","دمج المنتج مع مصادر الرصد الأخرى"]','تشغيل رادارات الطقس وتحليل منتجاتها'),
('radar-mosaic-and-compositing','دمج رادارات متعددة في فسيفساء موحدة','التغطية والتداخل وتوحيد الشبكات والأزمنة.','{"blocks":[{"type":"text","text":"يتناول الدرس دمج رادارات متعددة في فسيفساء موحدة ضمن تطبيقات الرصد الجوي والاستشعار عن بعد، مع ربط المبدأ الفيزيائي بالمنتج التشغيلي."},{"type":"text","text":"المفهوم الرئيس: التغطية والتداخل وتوحيد الشبكات والأزمنة.، ويجب تفسيره مع معرفة خصائص الجهاز والهندسة والظروف البيئية."},{"type":"text","text":"يبدأ التحليل بتحديد مصدر البيانات وإصدار المنتج والتوقيت والإحداثيات والوحدات والدقة المكانية والزمنية."},{"type":"text","text":"تراجع بيانات المعايرة والبيانات الوصفية وأعلام الجودة قبل تفسير القيم أو مقارنتها."},{"type":"text","text":"تحدد القيود المرتبطة بالمدى وزاوية الرصد والتضاريس والسحب والسطح والتداخل بين الإشارات بحسب نوع المستشعر."},{"type":"text","text":"تفسر المنتجات على أنها قياسات أو استرجاعات لها افتراضات، وليست وصفاً كاملاً مباشراً لكل خصائص الغلاف الجوي."},{"type":"text","text":"تدمج المنتجات مع المحطات والسبر والنماذج عند الحاجة، مع مراعاة اختلاف أوقات الرصد ومجالات التغطية."},{"type":"text","text":"تستخدم المقارنات الزمنية والمكانية لاكتشاف التطور والأنماط، مع تجنب تفسير الفجوات على أنها غياب للظاهرة."},{"type":"text","text":"توثق خطوات المعالجة والمرشحات والتحويلات وإعدادات العرض حتى تكون النتيجة قابلة لإعادة الإنتاج."},{"type":"text","text":"تقيّم جودة المنتج بمقارنته بمرجع مستقل وبفهم طبيعة الخطأ والتحيز وعدم اليقين."},{"type":"text","text":"مثال تطبيقي: إعداد خريطة تحليلية تتضمن المنتج الأصلي وأعلام الجودة ومناطق الثقة وملاحظات التحقق الأرضي."},{"type":"callout","text":"الخلاصة: القيمة التشغيلية للاستشعار عن بعد تعتمد على فهم القياس وحدوده ودمجه مع مصادر الرصد الأخرى."}]}',2620,60,'["شرح المبدأ الفيزيائي للمنتج","تقييم جودة القياس وحدود الاسترجاع","دمج المنتج مع مصادر الرصد الأخرى"]','تشغيل رادارات الطقس وتحليل منتجاتها'),
