('radar-nowcasting-products','منتجات التنبؤ الآني المعتمدة على الرادار','الاستقراء الحركي ومجالات الهطول قصيرة الأمد.','{"blocks":[{"type":"text","text":"يتناول الدرس منتجات التنبؤ الآني المعتمدة على الرادار ضمن تطبيقات الرصد الجوي والاستشعار عن بعد، مع ربط المبدأ الفيزيائي بالمنتج التشغيلي."},{"type":"text","text":"المفهوم الرئيس: الاستقراء الحركي ومجالات الهطول قصيرة الأمد.، ويجب تفسيره مع معرفة خصائص الجهاز والهندسة والظروف البيئية."},{"type":"text","text":"يبدأ التحليل بتحديد مصدر البيانات وإصدار المنتج والتوقيت والإحداثيات والوحدات والدقة المكانية والزمنية."},{"type":"text","text":"تراجع بيانات المعايرة والبيانات الوصفية وأعلام الجودة قبل تفسير القيم أو مقارنتها."},{"type":"text","text":"تحدد القيود المرتبطة بالمدى وزاوية الرصد والتضاريس والسحب والسطح والتداخل بين الإشارات بحسب نوع المستشعر."},{"type":"text","text":"تفسر المنتجات على أنها قياسات أو استرجاعات لها افتراضات، وليست وصفاً كاملاً مباشراً لكل خصائص الغلاف الجوي."},{"type":"text","text":"تدمج المنتجات مع المحطات والسبر والنماذج عند الحاجة، مع مراعاة اختلاف أوقات الرصد ومجالات التغطية."},{"type":"text","text":"تستخدم المقارنات الزمنية والمكانية لاكتشاف التطور والأنماط، مع تجنب تفسير الفجوات على أنها غياب للظاهرة."},{"type":"text","text":"توثق خطوات المعالجة والمرشحات والتحويلات وإعدادات العرض حتى تكون النتيجة قابلة لإعادة الإنتاج."},{"type":"text","text":"تقيّم جودة المنتج بمقارنته بمرجع مستقل وبفهم طبيعة الخطأ والتحيز وعدم اليقين."},{"type":"text","text":"مثال تطبيقي: إعداد خريطة تحليلية تتضمن المنتج الأصلي وأعلام الجودة ومناطق الثقة وملاحظات التحقق الأرضي."},{"type":"callout","text":"الخلاصة: القيمة التشغيلية للاستشعار عن بعد تعتمد على فهم القياس وحدوده ودمجه مع مصادر الرصد الأخرى."}]}',2650,60,'["شرح المبدأ الفيزيائي للمنتج","تقييم جودة القياس وحدود الاسترجاع","دمج المنتج مع مصادر الرصد الأخرى"]','تشغيل رادارات الطقس وتحليل منتجاتها'),
('satellite-orbit-and-scan-geometry','مدارات الأقمار وهندسة المسح','الثابتة والمدارية وزاوية الرؤية والتغطية.','{"blocks":[{"type":"text","text":"يتناول الدرس مدارات الأقمار وهندسة المسح ضمن تطبيقات الرصد الجوي والاستشعار عن بعد، مع ربط المبدأ الفيزيائي بالمنتج التشغيلي."},{"type":"text","text":"المفهوم الرئيس: الثابتة والمدارية وزاوية الرؤية والتغطية.، ويجب تفسيره مع معرفة خصائص الجهاز والهندسة والظروف البيئية."},{"type":"text","text":"يبدأ التحليل بتحديد مصدر البيانات وإصدار المنتج والتوقيت والإحداثيات والوحدات والدقة المكانية والزمنية."},{"type":"text","text":"تراجع بيانات المعايرة والبيانات الوصفية وأعلام الجودة قبل تفسير القيم أو مقارنتها."},{"type":"text","text":"تحدد القيود المرتبطة بالمدى وزاوية الرصد والتضاريس والسحب والسطح والتداخل بين الإشارات بحسب نوع المستشعر."},{"type":"text","text":"تفسر المنتجات على أنها قياسات أو استرجاعات لها افتراضات، وليست وصفاً كاملاً مباشراً لكل خصائص الغلاف الجوي."},{"type":"text","text":"تدمج المنتجات مع المحطات والسبر والنماذج عند الحاجة، مع مراعاة اختلاف أوقات الرصد ومجالات التغطية."},{"type":"text","text":"تستخدم المقارنات الزمنية والمكانية لاكتشاف التطور والأنماط، مع تجنب تفسير الفجوات على أنها غياب للظاهرة."},{"type":"text","text":"توثق خطوات المعالجة والمرشحات والتحويلات وإعدادات العرض حتى تكون النتيجة قابلة لإعادة الإنتاج."},{"type":"text","text":"تقيّم جودة المنتج بمقارنته بمرجع مستقل وبفهم طبيعة الخطأ والتحيز وعدم اليقين."},{"type":"text","text":"مثال تطبيقي: إعداد خريطة تحليلية تتضمن المنتج الأصلي وأعلام الجودة ومناطق الثقة وملاحظات التحقق الأرضي."},{"type":"callout","text":"الخلاصة: القيمة التشغيلية للاستشعار عن بعد تعتمد على فهم القياس وحدوده ودمجه مع مصادر الرصد الأخرى."}]}',2660,60,'["شرح المبدأ الفيزيائي للمنتج","تقييم جودة القياس وحدود الاسترجاع","دمج المنتج مع مصادر الرصد الأخرى"]','الأقمار الصناعية والدمج متعدد المصادر'),
('satellite-visible-ir-water-vapor','القنوات المرئية وتحت الحمراء وبخار الماء','الاختلاف الطيفي وتفسير خصائص السحب والرطوبة.','{"blocks":[{"type":"text","text":"يتناول الدرس القنوات المرئية وتحت الحمراء وبخار الماء ضمن تطبيقات الرصد الجوي والاستشعار عن بعد، مع ربط المبدأ الفيزيائي بالمنتج التشغيلي."},{"type":"text","text":"المفهوم الرئيس: الاختلاف الطيفي وتفسير خصائص السحب والرطوبة.، ويجب تفسيره مع معرفة خصائص الجهاز والهندسة والظروف البيئية."},{"type":"text","text":"يبدأ التحليل بتحديد مصدر البيانات وإصدار المنتج والتوقيت والإحداثيات والوحدات والدقة المكانية والزمنية."},{"type":"text","text":"تراجع بيانات المعايرة والبيانات الوصفية وأعلام الجودة قبل تفسير القيم أو مقارنتها."},{"type":"text","text":"تحدد القيود المرتبطة بالمدى وزاوية الرصد والتضاريس والسحب والسطح والتداخل بين الإشارات بحسب نوع المستشعر."},{"type":"text","text":"تفسر المنتجات على أنها قياسات أو استرجاعات لها افتراضات، وليست وصفاً كاملاً مباشراً لكل خصائص الغلاف الجوي."},{"type":"text","text":"تدمج المنتجات مع المحطات والسبر والنماذج عند الحاجة، مع مراعاة اختلاف أوقات الرصد ومجالات التغطية."},{"type":"text","text":"تستخدم المقارنات الزمنية والمكانية لاكتشاف التطور والأنماط، مع تجنب تفسير الفجوات على أنها غياب للظاهرة."},{"type":"text","text":"توثق خطوات المعالجة والمرشحات والتحويلات وإعدادات العرض حتى تكون النتيجة قابلة لإعادة الإنتاج."},{"type":"text","text":"تقيّم جودة المنتج بمقارنته بمرجع مستقل وبفهم طبيعة الخطأ والتحيز وعدم اليقين."},{"type":"text","text":"مثال تطبيقي: إعداد خريطة تحليلية تتضمن المنتج الأصلي وأعلام الجودة ومناطق الثقة وملاحظات التحقق الأرضي."},{"type":"callout","text":"الخلاصة: القيمة التشغيلية للاستشعار عن بعد تعتمد على فهم القياس وحدوده ودمجه مع مصادر الرصد الأخرى."}]}',2670,60,'["شرح المبدأ الفيزيائي للمنتج","تقييم جودة القياس وحدود الاسترجاع","دمج المنتج مع مصادر الرصد الأخرى"]','الأقمار الصناعية والدمج متعدد المصادر'),
